-- ==========================================================
-- HR ANALYTICS DATABASE: full data from your 24 CSV files
-- Standard SQL (MySQL / PostgreSQL compatible). 24 tables.
-- MySQL: run as-is. PostgreSQL: delete the next two lines.
-- ==========================================================
CREATE DATABASE IF NOT EXISTS hr_analytics;
USE hr_analytics;

-- ----- departments (8 rows) -----
DROP TABLE IF EXISTS departments;
CREATE TABLE departments (
    department_id INT NOT NULL PRIMARY KEY,
    department_name VARCHAR(33)
);

-- ----- locations (8 rows) -----
DROP TABLE IF EXISTS locations;
CREATE TABLE locations (
    location_id INT NOT NULL PRIMARY KEY,
    city VARCHAR(20),
    state VARCHAR(20),
    country VARCHAR(20)
);

-- ----- job_roles (17 rows) -----
DROP TABLE IF EXISTS job_roles;
CREATE TABLE job_roles (
    role_id INT NOT NULL PRIMARY KEY,
    department_id INT,
    role_name VARCHAR(39),
    job_family VARCHAR(20),
    salary_min INT,
    salary_max INT
);

-- ----- salary_grades (5 rows) -----
DROP TABLE IF EXISTS salary_grades;
CREATE TABLE salary_grades (
    grade_id INT NOT NULL PRIMARY KEY,
    grade_code VARCHAR(20),
    min_salary INT,
    max_salary INT
);

-- ----- exit_reasons (8 rows) -----
DROP TABLE IF EXISTS exit_reasons;
CREATE TABLE exit_reasons (
    exit_reason_id INT NOT NULL PRIMARY KEY,
    exit_reason VARCHAR(37)
);

-- ----- benefits (6 rows) -----
DROP TABLE IF EXISTS benefits;
CREATE TABLE benefits (
    benefit_id INT NOT NULL PRIMARY KEY,
    benefit_name VARCHAR(28),
    benefit_category VARCHAR(20),
    annual_cost_per_employee INT
);

-- ----- training_programs (10 rows) -----
DROP TABLE IF EXISTS training_programs;
CREATE TABLE training_programs (
    training_id INT NOT NULL PRIMARY KEY,
    training_name VARCHAR(55),
    training_category VARCHAR(20),
    duration_hours INT,
    cost_per_employee INT
);

-- ----- survey_questions (5 rows) -----
DROP TABLE IF EXISTS survey_questions;
CREATE TABLE survey_questions (
    question_id INT NOT NULL PRIMARY KEY,
    question_text VARCHAR(75),
    survey_category VARCHAR(20)
);

-- ----- employees (1200 rows) -----
DROP TABLE IF EXISTS employees;
CREATE TABLE employees (
    employee_id INT NOT NULL PRIMARY KEY,
    employee_name VARCHAR(27),
    gender VARCHAR(20),
    hire_date DATE,
    exit_date DATE,
    department_id INT,
    role_id INT,
    manager_id INT,
    location_id INT,
    employment_status VARCHAR(20),
    recruitment_source VARCHAR(27),
    education_level VARCHAR(20),
    grade_id INT,
    current_salary INT
);

-- ----- employee_analytics_master (1200 rows) -----
DROP TABLE IF EXISTS employee_analytics_master;
CREATE TABLE employee_analytics_master (
    employee_id INT NOT NULL PRIMARY KEY,
    employee_name VARCHAR(27),
    gender VARCHAR(20),
    hire_date DATE,
    exit_date DATE,
    employment_status VARCHAR(20),
    department_name VARCHAR(33),
    role_name VARCHAR(39),
    job_family VARCHAR(20),
    city VARCHAR(20),
    recruitment_source VARCHAR(27),
    education_level VARCHAR(20),
    grade_code VARCHAR(20),
    current_salary INT,
    manager_id INT,
    exit_reason VARCHAR(37),
    manager_rating DECIMAL(12,4),
    would_rehire VARCHAR(20),
    avg_perf_score DECIMAL(12,4),
    promotions_count INT,
    avg_engagement DECIMAL(12,4),
    absenteeism_rate DECIMAL(12,4),
    tenure_years DECIMAL(12,4),
    attrition_flag INT
);

-- ----- salary_history (2771 rows) -----
DROP TABLE IF EXISTS salary_history;
CREATE TABLE salary_history (
    salary_history_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    effective_date DATE,
    annual_salary INT,
    change_reason VARCHAR(27)
);

-- ----- employee_exit_details (270 rows) -----
DROP TABLE IF EXISTS employee_exit_details;
CREATE TABLE employee_exit_details (
    exit_detail_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    exit_date DATE,
    exit_reason_id INT,
    manager_rating INT,
    would_rehire VARCHAR(20),
    exit_interview_completed VARCHAR(20)
);

-- ----- employee_benefits (5397 rows) -----
DROP TABLE IF EXISTS employee_benefits;
CREATE TABLE employee_benefits (
    employee_benefit_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    benefit_id INT,
    start_date DATE,
    end_date DATE,
    benefit_status VARCHAR(20)
);

-- ----- employee_training (2391 rows) -----
DROP TABLE IF EXISTS employee_training;
CREATE TABLE employee_training (
    employee_training_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    training_id INT,
    training_date DATE,
    completion_status VARCHAR(20),
    score DECIMAL(12,4)
);

-- ----- performance_reviews (3147 rows) -----
DROP TABLE IF EXISTS performance_reviews;
CREATE TABLE performance_reviews (
    review_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    review_year INT,
    review_date DATE,
    performance_score DECIMAL(12,4),
    performance_rating VARCHAR(30),
    training_hours INT
);

-- ----- promotions (142 rows) -----
DROP TABLE IF EXISTS promotions;
CREATE TABLE promotions (
    promotion_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    promotion_date DATE,
    previous_role_id INT,
    new_role_id INT,
    promotion_reason VARCHAR(27)
);

-- ----- engagement_surveys (11580 rows) -----
DROP TABLE IF EXISTS engagement_surveys;
CREATE TABLE engagement_surveys (
    survey_response_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    survey_year INT,
    question_id INT,
    score INT,
    survey_date DATE
);

-- ----- attendance_monthly (33356 rows) -----
DROP TABLE IF EXISTS attendance_monthly;
CREATE TABLE attendance_monthly (
    attendance_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    attendance_year INT,
    attendance_month INT,
    working_days INT,
    present_days INT,
    leave_days INT,
    absentee_days INT,
    wfh_days INT
);

-- ----- onboarding (1200 rows) -----
DROP TABLE IF EXISTS onboarding;
CREATE TABLE onboarding (
    onboarding_id INT NOT NULL PRIMARY KEY,
    employee_id INT,
    joining_date DATE,
    onboarding_completion_date DATE,
    onboarding_status VARCHAR(20),
    documents_verified VARCHAR(20)
);

-- ----- job_requisitions (350 rows) -----
DROP TABLE IF EXISTS job_requisitions;
CREATE TABLE job_requisitions (
    requisition_id INT NOT NULL PRIMARY KEY,
    role_id INT,
    department_id INT,
    location_id INT,
    opening_date DATE,
    closing_date DATE,
    positions_count INT,
    requisition_status VARCHAR(20),
    requisition_reason VARCHAR(27)
);

-- ----- candidates (3200 rows) -----
DROP TABLE IF EXISTS candidates;
CREATE TABLE candidates (
    candidate_id INT NOT NULL PRIMARY KEY,
    candidate_name VARCHAR(27),
    gender VARCHAR(20),
    experience_years INT,
    education_level VARCHAR(20),
    recruitment_source VARCHAR(27),
    application_date DATE
);

-- ----- job_applications (3200 rows) -----
DROP TABLE IF EXISTS job_applications;
CREATE TABLE job_applications (
    application_id INT NOT NULL PRIMARY KEY,
    candidate_id INT,
    requisition_id INT,
    application_date DATE,
    application_status VARCHAR(20)
);

-- ----- interviews (2789 rows) -----
DROP TABLE IF EXISTS interviews;
CREATE TABLE interviews (
    interview_id INT NOT NULL PRIMARY KEY,
    application_id INT,
    round_number INT,
    interview_date DATE,
    interview_type VARCHAR(20),
    interview_score DECIMAL(12,4),
    interview_result VARCHAR(20)
);

-- ----- job_offers (846 rows) -----
DROP TABLE IF EXISTS job_offers;
CREATE TABLE job_offers (
    offer_id INT NOT NULL PRIMARY KEY,
    application_id INT,
    offer_date DATE,
    offered_salary INT,
    offer_status VARCHAR(20)
);
